skipRunner: async (runnerId) => {
  try {
    // Skip the current task for this runner by calling the skip action
    // Note: This uses the existing skipCurrent logic but scoped to the runner
    await api.post(`/runners/${encodeURIComponent(runnerId)}/skip`);
    return { success: true };
  } catch (error) {
    return { success: false, error: error.message };
  }
},

