app.post("/runners/:id/skip", async (request, reply) => {
	// Skip the current task for this runner
	try {
		const runner = authedRunner(request);
		const hold = claimStore.liveHoldFor(runner.runnerId);
		if (!hold) {
			return reply.status(404).send({ error: "Runner has no active task to skip" });
		}
		// Use the stage navigation skip logic
		const projectId = resolveAndGuardProject(
			request.body?.projectId || request.query?.projectId,
			reply,
		);
		if (!projectId) return;
		const task = taskStore.getTask(projectId, hold.taskId);
		if (!task) {
			reply.status(404).send({ error: "Task not found" });
			return;
		}
		// Skip the current stage for this task
		const stageNav = deps.stageNavigation || {
			skipStage: async (pid, tid) => {
				const execution = executionLedger.executionFor(taskId);
				if (!execution) {
					throw new Error("No execution found");
				}
				executionLedger.advanceStage(execution.executionId, { skip: true });
				return { success: true };
			},
		};
		await stageNav.skipStage(projectId, hold.taskId);
		return { success: true };
	} catch (err) {
		return sendStoreError(reply, err);
	}
});

